class NotificationService {
  private final NotificationStore store;
  private final SenderFactory senders;
  private final RateLimiter limiter;
  private final QueueProducer producer;

  // Intake: fast, idempotent, durable. Never calls provider here.
  public String submit(SendRequest req) {
    if (req.requestId() == null || req.userId() == null) throw new IllegalArgumentException("requestId+userId required");
    // Trade-off: DB check on intake costs ~5ms but makes retries safe.
    // Without it, client retries during a timeout create duplicates.
    return store.insertIfAbsent(req.requestId(), () -> {
      Notification n = new Notification(req, "QUEUED");
      store.persist(n);              // durability boundary
      producer.publish(topicFor(req), n); // partitioned by userId
      return n.id();
    });
  }

  // Worker path: one invocation per attempt, per channel.
  public void dispatch(Notification n, String channel) {
    if (!limiter.allow(n.userId(), channel, n.priority())) {
      store.markThrottled(n.id(), channel);
      return; // re-enqueued by scheduler, not retried as failure
    }
    try {
      Receipt r = senders.resolve(channel).send(n.rendered());
      store.markSent(n.id(), channel, r.providerId());
    } catch (ProviderException e) {
      // Trade-off: fail open to fallback only for non-critical opt-outs.
      store.appendAttempt(n.id(), channel, e.code());
      throw e; // delay-queue schedules backoff; breaker counts it
    }
  }
  private String topicFor(SendRequest r) {
    return r.priority().name().toLowerCase() + "." + r.channelHint();
  }
}
